+
+import org.junit.Test;
+
+import static org.junit.Assert.*;
+
+/**
+ * Tests for VelocityTemplateService focusing on security and functionality.
+ */
+public class VelocityTemplateServiceTest {
+
+    private final VelocityTemplateService service = new VelocityTemplateService();
+
+    @Test
+    public void testLegitimateTemplateRendersCorrectly() {
+        String template = "<div class=\"dashboard\">\n" +
+                "    <h1>Welcome, user $userId</h1>\n" +
+                "    <div class=\"stats\">\n" +
+                "        <p>User ID: $userId</p>\n" +
+                "    </div>\n" +
+                "</div>";
+        String result = service.renderUserDashboard("user123", template);
+        assertTrue("Template should render userId", result.contains("user123"));
+        assertTrue("Template should preserve HTML structure", result.contains("<div class=\"dashboard\">"));
+    }
+
+    @Test
+    public void testSstiRuntimeAccessIsBlocked() {
+        // Attempt to access Runtime through template injection.
+        // SecureUberspector silently blocks the method call (returns null)
+        // rather than throwing an exception. The template completes with
+        // empty output since the #set fails.
+        String maliciousTemplate = "#set($rt = $userId.getClass().forName('java.lang.Runtime').getRuntime())";
+        String result = service.renderUserDashboard("test", maliciousTemplate);
+        // Verify the attack was blocked - output is empty (no exception, but
+        // no successful execution either)
+        assertEquals("SSTI Runtime access should be silently blocked", "", result);
+    }
+
+    @Test
+    public void testSstiProcessBuilderIsBlocked() {
+        // Attempt to use ProcessBuilder through template injection
+        String maliciousTemplate = "#set($pb = $userId.getClass().forName('java.lang.ProcessBuilder'))";
+        String result = service.renderUserDashboard("test", maliciousTemplate);
+        // The blocked method returns null, so the template produces empty output
+        assertEquals("SSTI ProcessBuilder access should be silently blocked", "", result);
+    }
+
+    @Test
+    public void testXssInUserIdIsEscaped() {
+        // XSS attempt through userId that gets inserted into template
+        String template = "<div>$userId</div>";
+        String xssPayload = "<script>alert('xss')</script>";
+        String result = service.renderUserDashboard(xssPayload, template);
+        // The HTML should be escaped
+        assertTrue("XSS payload should be HTML-escaped", result.contains("&lt;script&gt;"));
+        assertFalse("Raw script tags should not appear", result.contains("<script>"));
+    }
+
+    @Test
+    public void testNullDashboardTemplateReturnsErrorMessage() {
+        String result = service.renderUserDashboard("user1", null);
+        assertTrue("Null template should return error message",
+                result.contains("empty"));
+    }
+
+    @Test
